service.description:
Internal: tells the screens of the tenant to fetch again, there is nothing
            else in the message. Runs on a thread without a user. Topics are not per tenant,
            so it goes to the users of the tenant only.

actions.script:
def lineTotal = { line ->
    orderItems.findAll({ (it.orderItemSeqId == line.orderItemSeqId
            || it.parentItemSeqId == line.orderItemSeqId) as boolean })
        .sum(0.0, { (it.unitAmount ?: 0.0) * (it.quantity ?: 0.0) }) }
def byShare = posLines.groupBy({ it.splitNo ?: 1 }).sort()
def left = total
def numbers = byShare.keySet().toList()
numbers.each { number ->
    def amount = number == numbers.last() ? left
        : byShare[number].sum(0.0, lineTotal).setScale(2, BigDecimal.ROUND_HALF_UP)
    left -= amount
    shares.add([splitNo: number, amount: amount.toString()])
}
